// Get the full JSON output from the previous node
const inputData = $input.first().json;

// 1. Drill down to the text string (which has markdown)
const jsonString = inputData.content.parts[0].text;

// 2. Find the start and end of the actual JSON
const startIndex = jsonString.indexOf('{');
const endIndex = jsonString.lastIndexOf('}') + 1;

// 3. Slice out the clean JSON string
const cleanJsonString = jsonString.slice(startIndex, endIndex);

// 4. Parse the clean, valid JSON object
const parsedData = JSON.parse(cleanJsonString);

// 5. Return the clean, parsed data for the next nodes
return parsedData;

